    """Try to find if cell is enclosed by 7s forming a rectangle"""
    top = find_boundary_7(grid, r, c, (-1, 0))   # up
    bottom = find_boundary_7(grid, r, c, (1, 0))  # down
    left = find_boundary_7(grid, r, c, (0, -1))   # left
    right = find_boundary_7(grid, r, c, (0, 1))   # right

    if top and bottom and left and right:
